package com.bank.modern.concurrency;

import java.util.concurrent.ThreadFactory;
import java.util.concurrent.atomic.AtomicInteger;

// Produces threads named "<prefix>-thread-N", the pool-name-thread-N
// convention. This is what makes thread dumps and logs debuggable.
public class NamedThreadFactory implements ThreadFactory {
    private final String prefix;
    private final AtomicInteger counter = new AtomicInteger(0);

    public NamedThreadFactory(String prefix) { this.prefix = prefix; }

    @Override
    public Thread newThread(Runnable r) {
        // e.g. "settlement-pool-thread-1", "settlement-pool-thread-2"
        Thread t = new Thread(r, prefix + "-thread-" + counter.incrementAndGet());
        t.setDaemon(false);
        return t;
    }
}
