package com.bank.modern.service;

import com.bank.modern.concurrency.NamedThreadFactory;
import com.bank.modern.model.NavResult;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Logger;

// Modern replacement for ThreadGroup coordination:
//  - ExecutorService manages the pool, queuing, and Future results
//  - a parallel fan-out fetches balance + trades, then combines
public class PortfolioService {
    private static final Logger log = Logger.getLogger(PortfolioService.class.getName());
    private final ExecutorService pool;

    public PortfolioService() {
        // Named pool → every thread is identifiable in a dump.
        this.pool = Executors.newFixedThreadPool(4,
                new NamedThreadFactory("portfolio-pool"));
    }

    // Fan out two subtasks in parallel, combine into a NAV. ExecutorService
    // gives us Futures (result handling) that ThreadGroup never could.
    public NavResult calculateNav(String accountId)
            throws ExecutionException, InterruptedException {
        Future<BigDecimal> balanceF = pool.submit(() -> fetchBalance(accountId));
        Future<BigDecimal> tradesF  = pool.submit(() -> fetchTradesValue(accountId));

        BigDecimal balance = balanceF.get();   // propagates task exception
        BigDecimal trades  = tradesF.get();
        BigDecimal nav = balance.add(trades);
        log.info(() -> "NAV for " + accountId + " = " + nav
                + " computed on pool threads");
        return new NavResult(accountId, nav);
    }

    private BigDecimal fetchBalance(String accountId) {
        log.fine(() -> "fetchBalance on " + Thread.currentThread().getName());
        // Rajesh SAV2001 opening balance.
        return accountId.equals("SAV2001") ? new BigDecimal("1000000")
                                           : new BigDecimal("250000");
    }

    private BigDecimal fetchTradesValue(String accountId) {
        log.fine(() -> "fetchTradesValue on " + Thread.currentThread().getName());
        // Pretend the open trades are worth this much.
        return new BigDecimal("150000");
    }

    // The names of the threads this pool created, to show the convention.
    public List<String> createdThreadNames(int probe) throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(probe);
        java.util.List<String> names = new java.util.concurrent.CopyOnWriteArrayList<>();
        for (int i = 0; i < probe; i++) {
            pool.submit(() -> {
                names.add(Thread.currentThread().getName());
                try { latch.countDown(); Thread.sleep(20); }
                catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            });
        }
        latch.await(2, TimeUnit.SECONDS);
        return names;
    }

    public void shutdown() throws InterruptedException {
        pool.shutdown();                         // orderly stop (ThreadGroup had none)
        if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
            pool.shutdownNow();                  // interrupting stop
        }
    }
}
