package com.bank.modern;

import com.bank.modern.model.NavResult;
import com.bank.modern.service.PortfolioService;

import java.util.List;
import java.util.logging.*;

public class ThreadGroupDemo {
    private static final Logger log = Logger.getLogger(ThreadGroupDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ModernLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        // Show how racy and result-less the OLD ThreadGroup enumeration is.
        ThreadGroup group = Thread.currentThread().getThreadGroup();
        Thread[] snapshot = new Thread[group.activeCount()];
        int n = group.enumerate(snapshot);      // racy count — may be stale
        log.warning("ThreadGroup.enumerate returned " + n
                + " threads — count can be STALE, no results, no clean shutdown");

        // MODERN: named ExecutorService with Future results.
        PortfolioService service = new PortfolioService();
        NavResult rajesh = service.calculateNav("SAV2001");
        log.info(() -> "Rajesh NAV = " + rajesh.getNav());

        // Show the pool-name-thread-N naming convention in action.
        List<String> names = service.createdThreadNames(4);
        log.info(() -> "Pool created threads: " + names
                + " (readable in any thread dump)");

        service.shutdown();
        log.info("Pool shut down cleanly — something ThreadGroup could not do safely");
    }
}

// ─── Would be in ModernLogFormatter.java in a real project ───
class ModernLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] (%3$s) %4$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(),
                Thread.currentThread().getName(), r.getMessage());
    }
}
