package com.bank.modern;

import com.bank.modern.concurrency.NamedThreadFactory;
import com.bank.modern.model.NavResult;
import com.bank.modern.service.PortfolioService;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.ThreadFactory;

import static org.junit.jupiter.api.Assertions.*;

class ModernThreadManagementTest {

    @Test
    void factoryProducesPoolNameThreadNConvention() {
        ThreadFactory f = new NamedThreadFactory("settlement-pool");
        Thread t1 = f.newThread(() -> {});
        Thread t2 = f.newThread(() -> {});
        assertEquals("settlement-pool-thread-1", t1.getName());
        assertEquals("settlement-pool-thread-2", t2.getName());
    }

    @Test
    void executorReturnsResultUnlikeThreadGroup() throws Exception {
        PortfolioService service = new PortfolioService();
        NavResult result = service.calculateNav("SAV2001");
        // balance 1,000,000 + trades 150,000 = 1,150,000
        assertEquals(0, new BigDecimal("1150000").compareTo(result.getNav()));
        service.shutdown();
    }

    @Test
    void poolThreadsAreNamedForDebugging() throws Exception {
        PortfolioService service = new PortfolioService();
        List<String> names = service.createdThreadNames(4);
        assertFalse(names.isEmpty(), "pool must have created named threads");
        assertTrue(names.stream().allMatch(nm -> nm.startsWith("portfolio-pool-thread-")),
                "every pool thread follows pool-name-thread-N");
        service.shutdown();
    }

    @Test
    void poolShutsDownCleanly() throws Exception {
        PortfolioService service = new PortfolioService();
        service.calculateNav("CUR3001");
        assertDoesNotThrow(service::shutdown);
    }
}
